/// Each node has an associated drawing surface, which has the size of
/// the rectangle set when creating it.
///
/// Render nodes are meant to be transient; once they have been associated
/// to a [class@Gsk.Renderer] it's safe to release any reference you have on
/// them. All [class@Gsk.RenderNode]s are immutable, you can only specify their
/// properties during construction.
class GskRenderNode {
  GskRenderNode.fromPointer(this.handle, {this.owned = false});
  final ffi.Pointer<ffi.Void> handle;
  final bool owned;

  /// Draws the contents of a render node on a cairo context.
  ///
  /// Typically, you'll use this function to implement fallback rendering
  /// of render nodes on an intermediate Cairo context, instead of using
  /// the drawing context associated to a [class@Gdk.Surface]'s rendering buffer.
  ///
  /// For advanced nodes that cannot be supported using Cairo, in particular
  /// for nodes doing 3D operations, this function may fail.
  static final _gskRenderNodeDraw =
      gsk4Lookup<
            ffi.NativeFunction<
              ffi.Void Function(ffi.Pointer<ffi.Void>, ffi.Pointer<ffi.Void>)
            >
          >('gsk_render_node_draw')
          .asFunction<
            void Function(ffi.Pointer<ffi.Void>, ffi.Pointer<ffi.Void>)
          >();
  void draw(CairoContext cr) {
    _gskRenderNodeDraw(this.handle, cr.handle);
  }

  /// Returns the type of the render node.
  static final _gskRenderNodeGetNodeType =
      gsk4Lookup<ffi.NativeFunction<ffi.Int32 Function(ffi.Pointer<ffi.Void>)>>(
        'gsk_render_node_get_node_type',
      ).asFunction<int Function(ffi.Pointer<ffi.Void>)>();
  GskRenderNodeType getNodeType() {
    return GskRenderNodeType.fromValue(_gskRenderNodeGetNodeType(this.handle));
  }

  /// Acquires a reference on the given `GskRenderNode`.
  static final _gskRenderNodeRef =
      gsk4Lookup<
            ffi.NativeFunction<
              ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void>)
            >
          >('gsk_render_node_ref')
          .asFunction<ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void>)>();
  GskRenderNode ref() {
    return GskRenderNode.fromPointer(_gskRenderNodeRef(this.handle));
  }

  /// Serializes the @node for later deserialization via
  /// gsk_render_node_deserialize(). No guarantees are made about the format
  /// used other than that the same version of GTK will be able to deserialize
  /// the result of a call to gsk_render_node_serialize() and
  /// gsk_render_node_deserialize() will correctly reject files it cannot open
  /// that were created with previous versions of GTK.
  ///
  /// The intended use of this functions is testing, benchmarking and debugging.
  /// The format is not meant as a permanent storage format.
  static final _gskRenderNodeSerialize =
      gsk4Lookup<
            ffi.NativeFunction<
              ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void>)
            >
          >('gsk_render_node_serialize')
          .asFunction<ffi.Pointer<ffi.Void> Function(ffi.Pointer<ffi.Void>)>();
  GBytes serialize() {
    return GBytes.fromPointer(_gskRenderNodeSerialize(this.handle));
  }

  /// Releases a reference on the given `GskRenderNode`.
  ///
  /// If the reference was the last, the resources associated to the @node are
  /// freed.
  static final _gskRenderNodeUnref =
      gsk4Lookup<ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void>)>>(
        'gsk_render_node_unref',
      ).asFunction<void Function(ffi.Pointer<ffi.Void>)>();
  void unref() {
    _gskRenderNodeUnref(this.handle);
  }

  /// This function is equivalent to calling [method@Gsk.RenderNode.serialize]
  /// followed by [func@GLib.file_set_contents].
  ///
  /// See those two functions for details on the arguments.
  ///
  /// It is mostly intended for use inside a debugger to quickly dump a render
  /// node to a file for later inspection.
  static final _gskRenderNodeWriteToFile =
      gsk4Lookup<
            ffi.NativeFunction<
              ffi.Int32 Function(
                ffi.Pointer<ffi.Void>,
                ffi.Pointer<Utf8>,
                ffi.Pointer<ffi.Pointer<ffi.Void>>,
              )
            >
          >('gsk_render_node_write_to_file')
          .asFunction<
            int Function(
              ffi.Pointer<ffi.Void>,
              ffi.Pointer<Utf8>,
              ffi.Pointer<ffi.Pointer<ffi.Void>>,
            )
          >();
  bool writeToFile(String filename) {
    return withNativeString(filename, (nativeFilename) {
      final _error = calloc<ffi.Pointer<ffi.Void>>();
      try {
        final _ret = _gskRenderNodeWriteToFile(
          this.handle,
          nativeFilename.cast<Utf8>(),
          _error,
        );
        if (_error.value != ffi.nullptr) {
          throw GlibException.fromError(_error.value);
        }
        return (_ret) != 0;
      } finally {
        calloc.free(_error);
      }
    });
  }
}
